cat > /tmp/spec.pl <<'EOF'
use strict; use warnings;
my $BIN="/workspace/dataset/test5_executable";

sub asciilower { my $s=shift; $s =~ tr/A-Z/a-z/; return $s; }

sub convport {
  my $s=shift;
  return -1 unless $s =~ /^[\t\n\x0b\f\r ]*([+-]?)([0-9]+)/;
  my ($sg,$d)=($1,$2);
  (my $m = $d) =~ s/^0+//; $m = "0" if $m eq "";
  if ($sg eq '-') { return $m eq "0" ? 0 : -1; }
  return -1 if length($m) > 5;
  my $v = 0+$m;
  return ($v>=0 && $v<=65535) ? $v : -1;
}

sub spec {
  my $url=shift;
  my ($scheme,$host,$port,$path,$query)=("","",-1,"","");
  my $rest=$url;
  my $hp=index($rest,"#"); if($hp>=0){ $rest=substr($rest,0,$hp); }
  my $qp=index($rest,"?"); if($qp>=0){ $query=substr($rest,$qp+1); $rest=substr($rest,0,$qp); }
  my $sp=index($rest,"://");
  if($sp<0){ $path=$rest; return ($scheme,$host,$port,$path,$query); }
  $scheme=asciilower(substr($rest,0,$sp));
  $rest=substr($rest,$sp+3);
  my $sl=index($rest,"/");
  my $auth;
  if($sl>=0){ $auth=substr($rest,0,$sl); $path=substr($rest,$sl); }
  else { $auth=$rest; $path=""; }
  my $at=index($auth,"\@"); if($at>=0){ $auth=substr($auth,$at+1); }
  my $c=index($auth,":");
  if($c<0){ $host=$auth; return ($scheme,$host,$port,$path,$query); }
  $host=substr($auth,0,$c);
  $port=convport(substr($auth,$c+1));
  return ($scheme,$host,$port,$path,$query);
}

sub runbin {
  my $u=shift;
  open(my $fh,'-|',$BIN,$u) or die "fork";
  local $/; my $out=<$fh>; close($fh); $out="" unless defined $out;
  return $out;
}

sub esc { my $s=shift; $s=~s/([^\x20-\x7e])/sprintf("<%02X>",ord($1))/ge; return $s; }

my $n=0; my $bad=0;
sub check {
  my $u=shift; $n++;
  my @f=spec($u);
  my $exp=join("\n",@f)."\n";
  my $got=runbin($u);
  if($exp ne $got){ $bad++; print "DIVERGE input=[".esc($u)."]\n  expect=[".esc($exp)."]\n  actual=[".esc($got)."]\n"; }
}

# exhaustive over alphabets
my @A=(':','/','a','?','#','@','8');
sub gen { my ($alpha,$maxlen)=@_; my @cur=(""); for my $L (0..$maxlen){ my @next; for my $s (@cur){ check($s) if length($s)==$L; for my $c (@$alpha){ push @next,$s.$c; } } @cur=@next if $L<$maxlen; }
}
# simpler: iterative
sub genall { my ($alpha,$maxlen)=@_;
  my @cur=("");
  check("");
  for my $L (1..$maxlen){
    my @next;
    for my $s (@cur){ for my $c (@$alpha){ my $t=$s.$c; push @next,$t; check($t); } }
    @cur=@next;
  }
}
genall(\@A,4);
genall([':','/','a'],6);
genall([':','/','?','#'],5);
print "tested=$n diverged=$bad\n";
EOF
perl /tmp/spec.pl 2>&1 | tail -40

